  rw_cells bsegs m allocb [C8 (wz AVP_ALLOCIMPL); CB 8 jal] -> rblock_range allocb SZ_ALLOCIMPL -> addressable m allocb SZ_ALLOCIMPL ->
  (allocb + SZ_ALLOCIMPL <= as_FSB H \/ as_FSB H + AFS_SIZE <= allocb) ->
  AXStatics2 m ->
  stk bsegs m lo (bv_unsigned sp) -> lo + 176 + AFS_STACK <= bv_unsigned sp -> aceil <= lo ->
  mem_inv bsegs m ->
  bv_unsigned sp mod 16 = 0 -> tp = Z_to_bv 64 ATP -> ACONST m -> athr_cells m ->
  as_RFS H LF m -> (length LF < AFS_MAXLIVE)%nat ->
  stack0 m lo shi -> bv_unsigned sp + 64 <= shi ->
  evt bsegs (aor_seg1_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc LF AT ioc allocb lo shi m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 AT) (Z_to_bv 64 ioc) a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_A_ALLOC_OBJ_REGISTRY) fc None m (seg_rom bsegs)).
